        List<Integer> nums = (List<Integer>) data.get("nums");
        int n = nums.size();

        // Edge case: empty list
        if (n == 0) return 0;

        // Edge case: single element list
        if (n == 1) return nums.get(0);

        // Sort the list to maximize the number of coins
        Collections.sort(nums);

        // Initialize the dp array
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = nums.get(i);
        }

        // Fill the dp array using dynamic programming
        for (int len = 2; len <= n; len++) {
            for (int start = 0; start + len - 1 < n; start++) {
                int end = start + len - 1;
                int maxCoins = 0;
                for (int k = start; k < end; k++) {
                    int leftCoins = k > 0 ? dp[start][k - 1] : 0;
                    int rightCoins = k < end - 1 ? dp[k + 1][end] : 0;
                    int currentCoins = nums.get(start) * nums.get(k) * nums.get(end);
                    maxCoins = Math.max(maxCoins, leftCoins + rightCoins + currentCoins);
                }
                dp[start][end] = maxCoins;
            }
        }

        return dp[0][n - 1];
    }
}

